"""Evidence table with explicit observed fields; missing details are not invented."""
from mltn.common import ROOT,read,write
import pandas as pd,re,urllib.request,time
def main():
    out=ROOT/'literature';records=read(out/'screened_unique.json');unique={}
    for r in records:
        key=(r.get('doi') or r['title']).lower();old=unique.get(key)
        if old is None or r.get('pmcid'):unique[key]=r
    write(out/'screened_unique.json',list(unique.values()))
    # These abstracts were read against saved primary-source metadata.
    notes={
    '10.3390/w17081131':('TN','28922 points; 7 sites; 2020-11 to 2023-02','conductivity, CODMn, TP','At-CBiLSTM','split not established from abstract','RMSE .045 reported; inconsistent with MSE .005, verify full methods before reuse','surrogate sensor task; no transfer of accuracy to external-driver TN'),
    '10.1029/2024wr039207':('nitrate','95 sensors, 158282 daily rows; 2007-2022','meteorology, discharge, 31 static attributes; no nitrate lag','LSTM180day hidden256','temporal blocks and held basins; temporal training can contain later blocks','median temporal KGE .60 versus spatial .18','full-text audited; strict forward split retained here, no assumption time skill transfers spatially'),
    '10.3389/frwa.2024.1456647':('20 solutes','about500 catchments','flow, season/time; climate ablation','LSTM vs WRTDS','not established from abstract','LSTM did not markedly outperform WRTDS','simple flow-season baseline necessary; more features need not help'),
    '10.2166/ws.2023.164':('river water quality','Jiangnan plain; sample count unknown','inter-station water-quality correlations','GCN+LSTM','not established from abstract','R2 .977; RMSE .291','do not construct graph using held-out TN correlations; freeze physical directed graph'),
    '10.1016/j.watres.2026.126320':('nitrate+nitrite','1461 daily records; two rivers','lagged nitrate, pH, DO, temperature','TGCN-LSTM; 7-day lead','sequential70/30 and rolling-origin','R2 .965/.893; no lag drops to about .65-.75','auxiliary autoregressive task separately reported; DO excluded in this project'),
    '10.1016/j.jenvman.2026.129539':('nitrate','Iowa monitored sites; count unknown','high-frequency reference nitrate, discharge, day length','deep-learning transfer','not established from abstract','similarity of c-Q and seasonal drivers important; distance alone weak','reference-site TN task differs from independent external-driving model'),
    '10.1016/j.watres.2026.125613':('NO3 load','44 HUC12 subbasins;2001-2020','SWAT+ synthetic pretraining, inflows, watershed features','directed HydroGraphNet','temporal and spatial extrapolation','real-data mean nitrate load NSE .626 reported','physical graph useful hypothesis; synthetic physical-model pretraining excluded from pure-ML main line'),
    '10.13227/j.hjkx.202507105':('TN and nitrogen species','2024 farmland drainage ditch, sample count unknown','UAV multispectral reflectance','RF/XGB/CatBoost, stacked RF-XGB','test split details unknown from abstract','TN test R2 .89; RMSE .68 for stack; extreme peaks underpredicted','spectral proxy differs from H1 drivers; amplification alone not adequate'),
    '10.1051/limn/2025010':('WQI/DO/EC','monthly2019-2021; single station','water level, water quality,temperature,P','GNN+Transformer','not established from abstract','R2>.92 for5day stated','monthly sampling versus5day support unresolved; no unobserved daily labels assumed'),
    '10.5194/egusphere-egu25-9125':('TON','390stations, about1500annual/seasonal samples2018-2021','land, tile drainage, elevation,lakes','ML and quantile regression','conference abstract; details missing','annual RMSE .20mg/L','static-domain shift can bias regional prediction; meeting evidence only'),
    '10.5194/egusphere-egu22-8223':('nitrogen','115global largebasins;1992-2010','gridded livestock,fertilizer,environment','RF monthly','conference abstract; details missing','15% global concentration increase attributed in abstract','independent agriculture predictors justified; importance is not causality'),
    '10.1038/s41598-026-48132-y':('urban water quality','Zhongshan; counts unknown','past water quality/residual components','ARIMA-LSTM','not established from abstract','hybrid better than single models, no numerical claim here','autoregression separate evidence line; decomposition fit only past training data'),
    '10.1016/j.jconhyd.2026.105024':('TN/TP','2016-01 to2025-10 WQMN; count unknown','sensor-measurable water-quality variables','cluster RF/XGB/MLP','not established from abstract','TN R2 gain up to .045','quality-derived clustering risks leakage; physical partitions retained'),
    '10.1016/j.ese.2026.100755':('chlorophyll a','tworeservoirs; counts unknown','lagged biomass,nutrient,temp','nine temporal architectures','not established from abstract','1-7day NSE up to .88;8-15day up to .83','ecological horizon matters; chlorophyll task not TN accuracy evidence'),
    '10.1007/s10661-026-15786-0':('river height for water-quality sampling','15years hourly','rain,flow,river height','CatBoost 1-48h','not established from abstract','skill decreases at24-48h andextremeevents','event sampling bias requires separate evaluation; hydrology target not TN'),
    '10.54097/bzqp1q29':('water quality','Liuxi; counts unknown','decomposed target time series','ICEEMDAN-WOA-LSTM','not established from abstract','superiority claim only','whole-series decomposition prohibited; evidence quality insufficient for accuracy promise'),
    '10.52783/jisem.v10i44s.8600':('river water quality','unknown','autoregressive history and future context claimed','deep autoregression BiLSTM','future context language; causal forecast not established','error42.6% reduction claim','explicit causal-history gate; use unidirectional networks'),
    '10.1016/j.wroa.2023.100207':('water-quality LSTM review','review','autoregressivewater-quality, meteorology,static','LSTM/CNN/attention','review of heterogeneous tasks','no common-score inference','full text; distinguish imputation, short forecast and unseen-catchment prediction')}
    rows=[]
    for doi,n in notes.items():
        r=unique.get(doi,{"doi":doi});depth='full-text interpreted' if doi in ['10.1016/j.wroa.2023.100207','10.1029/2024wr039207'] else 'abstract interpreted'
        rows.append(dict(doi=doi,title=r.get('title'),evidence=depth,target=n[0],support=n[1],inputs=n[2],route=n[3],split=n[4],reported_metrics=n[5],implementation_implication=n[6],url='https://doi.org/'+doi))
    # Official executable/documentation audits, not additional empirical water-quality papers.
    docs=[('RF','https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.RandomForestRegressor.html','bootstrap averaging, sample weights, n_jobs; training support only'),('ExtraTrees','https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.ExtraTreesRegressor.html','random split thresholds; sample weights; separate from boosting'),('XGBoost','https://xgboost.readthedocs.io/en/stable/tutorials/custom_metric_obj.html','custom objective, link and prediction margin semantics; exact aggregate gradient, approximate diagonal Hessian'),('LightGBM','https://lightgbm.readthedocs.io/en/latest/pythonapi/lightgbm.train.html','custom gradients/hessians, raw score; explicit initial intercept'),('CatBoost','https://catboost.ai/docs/en/concepts/python-reference_catboostregressor','CPU/GPU and weights; no daily pseudo-label joint objective'),('LSTM','https://docs.pytorch.org/docs/stable/generated/torch.nn.LSTM.html','unidirectional causal sequence; batch_first; no future context'),('GRU','https://docs.pytorch.org/docs/stable/generated/torch.nn.GRU.html','gated recurrent shared weights; final window hidden output'),('Transformer','https://docs.pytorch.org/docs/stable/generated/torch.nn.TransformerEncoder.html','causal mask plus positional encoding; training dropout off during inference'),('Conv1d','https://docs.pytorch.org/docs/stable/generated/torch.nn.Conv1d.html','left-only padding for causal dilated temporal convolution')]
    for name,url,note in docs:
        try:
            req=urllib.request.Request(url,headers={'User-Agent':'SPARROW-evidence-audit/1.0'})
            with urllib.request.urlopen(req,timeout=40) as f:raw=f.read()
            (out/f'implementation_{name}.html').write_bytes(raw);status='official documentation retrieved and interface checked'
        except Exception as e:status='interface checked in installed package; webpage unavailable: '+str(e)
        rows.append(dict(doi='',title=name,evidence='public implementation/documentation',target='algorithm implementation',support='not empirical water-quality dataset',inputs='same independent frozen feature contract',route=name,split='controlled by project train.py',reported_metrics='NSE not applicable',implementation_implication=note,url=url,retrieval_status=status));time.sleep(.3)
    pd.DataFrame(rows).to_csv(out/'detailed_evidence_table.csv',index=False,encoding='utf-8-sig');write(out/'detailed_review_receipt.json',dict(deduplicated_screen=len(unique),interpreted_studies=len(notes),public_implementations=len(docs),detailed_total=len(rows),full_text_interpreted=2,abstract_interpreted=len(notes)-2,unknown_fields='explicitly unknown, not filled from title',notes='2026 studies and conference abstracts explicitly distinguished; search relevance exclusions retained'))
if __name__=='__main__':main()
